    /**
     * Method to retrieve the Account via an FindAccountQuery
     * @return 	query	FindAccountQuery
     */
    @SuppressWarnings("unused")
    public Account find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Account - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Accounts
     *
     * @param	query	FindAllAccountQuery 
     * @return 	List<Account> 
     */
    @SuppressWarnings("unused")
    public List<Account> findAll( FindAllAccountQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Account - {0}", exc.getMessage() );
    	}
    	return null;
    }


